/**
 * Subtle noise over the app background (a 140pt tile of white noise at up to 4%).
 * Render it as the first child of a screen root; cards drawn on top of it
 * have solid fills, so they stay grain-free and stand out.
 * Generated by scripts/gen-grain.mjs.
 */
import { Image, StyleSheet, useWindowDimensions, View } from 'react-native';

const GRAIN = require('../../assets/images/grain.png');

export function Grain() {
  // iOS only tiles a "repeat" image across an explicit size, not an absolute fill.
  const { width, height } = useWindowDimensions();
  return (
    <View style={[StyleSheet.absoluteFill, { overflow: 'hidden' }]} pointerEvents="none" importantForAccessibility="no-hide-descendants" accessibilityElementsHidden>
      <Image source={GRAIN} resizeMode="repeat" style={{ position: 'absolute', top: 0, left: 0, width, height }} />
    </View>
  );
}
